u = int(input())
if u <= 100:
    energy = u * 3.5
elif u <= 200:
    energy = 350 + (u - 100) * 5
else:
    energy = 350 + 500 + (u - 200) * 8
print(f"{energy + 90:.2f}")

age, weight, hb, days = map(int, input().split())
ok = 18 <= age <= 65 and weight >= 50 and hb >= 12 and days >= 90
fails = 0
if age < 18 or age > 65:
    fails += 1
if weight < 50:
    fails += 1
if hb < 12:
    fails += 1
if days < 90:
    fails += 1
print("Eligible" if ok else f"Not Eligible - {fails} failed")
